CREATE   PROCEDURE [dbo].[usp_Product_Delete]
	@ProductId int
AS
BEGIN
	SET NOCOUNT ON;
	DELETE FROM dbo.Products WHERE ProductId = @ProductId;
	RETURN @@ROWCOUNT;
END;
GO
