    CREATE   PROCEDURE [dbo].[usp_Report_LowStock]
    AS
    BEGIN
        SET NOCOUNT ON;
        SELECT ProductId, Sku, Name, StockQty, ReorderLevel
        FROM dbo.Products 
        WHERE IsActive = 1 AND StockQty <= ReorderLevel
        ORDER BY StockQty, Name;
    END
