/****** Object:  StoredProcedure [dbo].[usp_Report_RecentActivity]    Script Date: Nov 7, 2026 3:47:35 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE   PROCEDURE [dbo].[usp_Report_RecentActivity]
AS
BEGIN
	SET NOCOUNT ON;
	SELECT TOP (10) ActivityDate, ActivityType, Description
	FROM
	(
		SELECT o.OrderDate AS ActivityDate, N'Order' AS ActivityType,
			   N'Order ' + o.OrderNumber + N' recorded for ' + CONVERT(nvarchar(30), o.Total) AS Description
		FROM dbo.Orders AS o
		UNION ALL
		SELECT il.CreatedAt, N'Inventory',
			   p.Name + N': ' + CONVERT(nvarchar(20), il.ChangeQty) + N' (' + il.Reason + N')'
		FROM dbo.InventoryLog AS il
		INNER JOIN dbo.Products AS p ON p.ProductId = il.ProductId
	) AS activity
	ORDER BY ActivityDate DESC;
END;
GO
/****** Object:  StoredProcedure [dbo].[usp_Report_SalesByCategory]    Script Date: Nov 7, 2026 3:47:35 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

    CREATE   PROCEDURE [dbo].[usp_Report_SalesByCategory] 
        @From DATETIME, 
        @To DATETIME
    AS
    BEGIN
        SET NOCOUNT ON;
        SELECT c.Name AS CategoryName, SUM(d.LineTotal) AS Revenue
        FROM dbo.OrderDetails d
        JOIN dbo.Orders o ON o.OrderId = d.OrderId
        JOIN dbo.Products p ON p.ProductId = d.ProductId
        JOIN dbo.Categories c ON c.CategoryId = p.CategoryId
        WHERE o.Status = N'Completed' AND o.OrderDate >= @From AND o.OrderDate < DATEADD(DAY, 1, @To)
        GROUP BY c.Name
        ORDER BY SUM(d.LineTotal) DESC;
    END
GO
/****** Object:  StoredProcedure [dbo].[usp_Report_TopProducts]    Script Date: Nov 7, 2026 3:47:35 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

    CREATE   PROCEDURE [dbo].[usp_Report_TopProducts] 
        @From DATETIME, 
        @To DATETIME, 
        @Top INT = 10
    AS
    BEGIN
        SET NOCOUNT ON;
        SELECT TOP (@Top) p.Name AS ProductName, SUM(d.Quantity) AS QtySold, SUM(d.LineTotal) AS Revenue
        FROM dbo.OrderDetails d
        JOIN dbo.Orders o ON o.OrderId = d.OrderId
        JOIN dbo.Products p ON p.ProductId = d.ProductId
        WHERE o.Status = N'Completed' AND o.OrderDate >= @From AND o.OrderDate < DATEADD(DAY, 1, @To)
        GROUP BY p.Name
        ORDER BY SUM(d.LineTotal) DESC;
    END
GO
